export function parseIpv4(text) {
    const p = text.split('.');
    if (p.length !== 4)
        return null;
    const out = [];
    for (const s of p) {
        if (!/^(0|[1-9]\d*)$/.test(s))
            return null;
        const n = Number(s);
        if (n > 255)
            return null;
        out.push(n);
    }
    return out;
}
